/**
 * Web K typing send path (tweb `appMessagesManager.setTyping` +
 * `input.ts:4254-4281`).
 *
 * The kernel RPC `SendTyping(chatID, action, proxy, ntp)` lands in this round;
 * the generated bindings are regenerated by the Lead afterwards, so the service
 * is cast through a local interface exactly like `telegramExtra.ts` does.
 *
 * tweb semantics: while the composer holds text it re-sends `typing` at most
 * once every 6 s; as soon as the field empties one `cancel` goes out. The
 * receiving side expires the last event after 6 s anyway
 * (`appProfileManager.onUpdateUserTyping`), so a dropped event is harmless.
 */
import { Service as AppService } from "../../bindings/tgdesk/internal/app";
import type { TypingAction } from "./typingStore";

export interface TypingNetwork {
  proxy: string;
  ntp: string;
}

/** tweb `input.ts:4276`: one `typing` per 6 s while the input stays non-empty. */
export const TYPING_SEND_INTERVAL_MS = 6000;

interface TypingBindings {
  SendTyping(
    chatID: string,
    action: string,
    proxy: string,
    ntp: string,
  ): Promise<void>;
}

const api = AppService as unknown as TypingBindings;

/** Last successful/attempted `typing` send per chat, for the composer throttle. */
const lastSentAt = new Map<string, number>();

/**
 * Sends one typing action now (no throttle). Resolves `true` when the RPC was
 * accepted and `false` when it failed; a failure is only logged, the composer
 * must not show it.
 */
export async function sendTyping(
  chatId: string,
  action: TypingAction,
  network?: TypingNetwork,
): Promise<boolean> {
  if (!chatId) {
    return false;
  }
  try {
    await api.SendTyping(
      chatId,
      action,
      network?.proxy ?? "",
      network?.ntp ?? "",
    );
    return true;
  } catch (error) {
    console.warn("[typing] SendTyping failed", error);
    return false;
  }
}

/**
 * Throttled composer entry point: `typing` is forwarded to the kernel at most
 * once per 6 s per chat, `cancel` goes out at once and resets the window.
 * Returns `true` when an RPC was fired.
 */
export function notifyTyping(
  chatId: string,
  action: TypingAction,
  network?: TypingNetwork,
): boolean {
  if (!chatId) {
    return false;
  }
  if (action === "cancel") {
    lastSentAt.delete(chatId);
    void sendTyping(chatId, "cancel", network);
    return true;
  }
  const now = Date.now();
  const last = lastSentAt.get(chatId) ?? 0;
  if (now - last < TYPING_SEND_INTERVAL_MS) {
    return false;
  }
  lastSentAt.set(chatId, now);
  void sendTyping(chatId, action, network).then((sent) => {
    // A failed event must not swallow the next 6 s window.
    if (!sent && lastSentAt.get(chatId) === now) {
      lastSentAt.delete(chatId);
    }
  });
  return true;
}

/**
 * Drops the throttle window of one chat (or all of them). The composer should
 * call it after sending a message and on chat switch/logout so the next chat's
 * first keystroke is forwarded immediately.
 */
export function resetTypingThrottle(chatId?: string): void {
  if (chatId) {
    lastSentAt.delete(chatId);
    return;
  }
  lastSentAt.clear();
}
